contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _minSum, uint _depositAmount, uint _collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_depositAmount)); require(_depositAmount <= 1000000000000000000000000000000);
        require(_collectAmount > 0);
        require(_depositAmount >= _collectAmount);
        require(_depositAmount >= _minSum);
        require(address(this).balance >= _depositAmount);

        c.SetMinSum(_minSum); if (__ESBMC_reverted()) return;
        c.Deposit{value: _depositAmount}(); if (__ESBMC_reverted()) return;

        uint256 balanceBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        bool reverted;
        c.Collect(_collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 balanceAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(!reverted && balanceAfter == balanceBefore - _collectAmount);
    }

    receive() external payable {}
}

