pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 _minSum, uint256 _depositAmount, uint256 _collectAmount) internal {
        _depositAmount = bound(_depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(_collectAmount > 0);
        vm.assume(_depositAmount >= _collectAmount);
        vm.assume(_depositAmount >= _minSum);
        vm.assume(address(this).balance >= _depositAmount);
        try c.SetMinSum(_minSum) {} catch { return; }
        try c.Deposit{value: _depositAmount}() {} catch { return; }
        uint256 balanceBefore;
        try c.balances(address(this)) returns (uint256 __r) { balanceBefore = __r; } catch { return; }
        bool reverted;
        try c.Collect(_collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balanceAfter;
        try c.balances(address(this)) returns (uint256 __r) { balanceAfter = __r; } catch { return; }
        assertTrue(!reverted && balanceAfter == balanceBefore - _collectAmount);
    }

    function testFuzz_run(uint256 _minSum, uint256 _depositAmount, uint256 _collectAmount) public {
        _run(_minSum, _depositAmount, _collectAmount);
    }

    receive() external payable {}
